class JsonViewer{
  constructor(json, name = "ROOT"){
    // check if json is string, if yes parse
    // else set this.json
    this.name = name
    this.json = undefined
    if("string" == typeof json){
      this.json = JSON.parse(json)
    }

    else {
      this.json = json
    }

  }

  render() {
    console.log("anyuthiong")
    console.log(this)

    function value_R(value){
      // match typeof value
      // - string
      // - number
      // - boolean
      // - object
      // - array
      // - null

      if ("string" == typeof value) return string_R(value)
      else if ("boolean" == typeof value) return bool_R(value)
      else if ("number" == typeof value) return number_R(value)
      else if (Array.isArray(value)) return array_R(value)
        // check for array first
      else if ("object" == typeof value) return object_R(value)

    }

    function array_R(arr){
      let open = sig(false)
      let arrow = mem(() => open() ? "▾":"▸")
      let toggle = () => open.set(!open())
      let show = mem(() => 
        open() ?
        html` 
        p -- ${arr.map((e, i) => value_pair_R([i + "", e]))}
        p -- ]
        `
        : 
        html` 
        span -- ..]
        `


      )
      return html`
       span.arrow [onclick=${toggle}] -- ${arrow}
       span.array -- [

       span -- ${show}

      `
    }

    function value_pair_R(pair){
     const [key, value] = pair
      console.log("key", key)
      console.log("value", value)
      return html`
      .json
        span.key -- ${key} 
        span -- ${" "}: 
        span.value -- ${() => value_R(value)}
      `
    }

    function string_R(str) {
      return html`span.string -- ${str}`
    }

    function bool_R(val) {
      let bool = val ? "true": "false"
      return html`span.bool -- ${bool}`
    }

    function number_R(num) {
      if (num === 0) console.log("ZEROO")
      console.log("NUMMM", num)
      return html`span.number -- ${num}`
    }

    function object_R(obj) {
      // should hold a 
      // closed or open

      return html`
       span.object -- {
       p -- ${Object.entries(obj).map(value_pair_R)}
       p -- }
      `
    }

    return value_pair_R([this.name, this.json])
  }



}

